    'ui_require_pin_to_play_any_channel': '\u0422\u0440\u0435\u0431\u043e\u0432\u0430\u0442\u044c PIN \u0434\u043b\u044f \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u044f \u043b\u044e\u0431\u043e\u0433\u043e \u043a\u0430\u043d\u0430\u043b\u0430 \u0438\u043b\u0438 \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u0430, \u0432\u043e \u0432\u0441\u0435\u0445 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f\u0445. \u041d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u043e\u0442 \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u044b\u0445 \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043e\u043a \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u0430/\u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0439.',
    'ui_restrict_playback': '\u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0442\u044c \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u0435',
    'ui_resume': '\u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u044c',
    'ui_resume_last_channel': '\u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u044c \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u043a\u0430\u043d\u0430\u043b',
    'ui_cache_vod_catalogue': '\u041a\u044d\u0448\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0424\u0438\u043b\u044c\u043c\u044b \u0438 \u0421\u0435\u0440\u0438\u0430\u043b\u044b',
    'ui_cache_vod_desc': 'Хранить каталог фильмов и сериалов на этом устройстве, чтобы приложение открывалось без повторной загрузки. Он обновляется автоматически через 30 дней, при смене источника плейлиста или при ручном обновлении плейлиста. Отключите, если предпочитаете свежую загрузку при каждом запуске.',
    'ui_scale_everything_in_the_app_up': '\u041c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u0443\u0439\u0442\u0435 \u0432\u0441\u0451 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0432\u0432\u0435\u0440\u0445 \u0438\u043b\u0438 \u0432\u043d\u0438\u0437 \u0434\u043b\u044f \u0443\u0434\u043e\u0431\u0441\u0442\u0432\u0430 \u0447\u0442\u0435\u043d\u0438\u044f. \u0412\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0441\u043f\u0438\u0441\u043a\u0438 \u043a\u0430\u043d\u0430\u043b\u043e\u0432, \u0433\u0438\u0434, \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0438 \u044d\u043a\u0440\u0430\u043d\u043d\u0443\u044e \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0443. \u0412\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u0432\u0438\u0434\u0435\u043e \u043d\u0435 \u0437\u0430\u0442\u0440\u0430\u0433\u0438\u0432\u0430\u0435\u0442\u0441\u044f.',
    'ui_sign_in_to_sync_your_playlists': '\u0412\u043e\u0439\u0434\u0438\u0442\u0435, \u0447\u0442\u043e\u0431\u044b \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0430\u0448\u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438, \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435, \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u043e\u0432, \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0439, \u0441\u043a\u0440\u044b\u0442\u044b\u0435 \u0438 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438 \u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0441\u0443\u0431\u0442\u0438\u0442\u0440\u043e\u0432 \u043d\u0430 \u0432\u0441\u0435\u0445 \u0432\u0430\u0448\u0438\u0445 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u0445. \u0411\u0435\u0441\u043f\u043b\u0430\u0442\u043d\u043e \u0438 \u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e.',
    'ui_small_10': '\u041c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0439 (-10%)',
    'ui_stalker_mag_portals_authenticate_by_mac': '\u041f\u043e\u0440\u0442\u0430\u043b\u044b Stalker/MAG \u0430\u0443\u0442\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043f\u043e MAC-\u0430\u0434\u0440\u0435\u0441\u0443. \u0411\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u0443 \u043d\u0443\u0436\u0435\u043d \u0442\u043e\u043b\u044c\u043a\u043e MAC; \u043d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u043c \u0442\u0430\u043a\u0436\u0435 \u0442\u0440\u0435\u0431\u0443\u044e\u0442\u0441\u044f \u0441\u0435\u0440\u0438\u0439\u043d\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 \u0438 ID \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 \u2014 \u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0438\u0445 \u043f\u0443\u0441\u0442\u044b\u043c\u0438, \u0435\u0441\u043b\u0438 \u043f\u0440\u043e\u0432\u0430\u0439\u0434\u0435\u0440 \u043d\u0435 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0438\u043b \u0438\u0445.',
    'ui_text_size': '\u0420\u0430\u0437\u043c\u0435\u0440 \u0442\u0435\u043a\u0441\u0442\u0430',
